const body = $input.first().json.body || $input.first().json || {};

const action = body.action || '';
const issue = body.issue || {};
const comment = body.comment || {};
const label = body.label || {};
const sender = body.sender?.login || '';

const labelName = (label.name || '').toLowerCase();
const issueNumber = issue.number || 0;
const issueTitle = issue.title || `Issue #${issueNumber}`;
const issueBody = issue.body || 'No description provided.';
const commentBody = comment.body || '';
const repo = body.repository?.full_name || 'conarwelsh/sous.tools';

let stage = 'skip';

// 1. Check label triggers
if (action === 'labeled') {
  if (labelName === 'ready' || labelName === 'agent:ready') {
    stage = 'ready';
  } else if (labelName === 'done' || labelName === 'agent:done') {
    stage = 'done';
  }
}

// 2. Check human reply triggers on issue comments
if (action === 'created' && comment.id && !sender.includes('[bot]') && !sender.includes('n8n') && !sender.includes('aider')) {
  stage = 'human_reply';
}

return [{
  json: {
    stage,
    action,
    issueNumber,
    issueTitle,
    issueBody,
    commentBody,
    sender,
    repo
  }
}];

const payload = $('Parse GitHub Payload').item.json;
const items = $input.all();

let commentsArray = [];
if (items.length > 0 && items[0].json) {
  const firstJson = items[0].json;
  if (Array.isArray(firstJson)) {
    commentsArray = firstJson;
  } else if (firstJson.body) {
    commentsArray = items.map(i => i.json);
  }
}

const last2 = commentsArray.slice(-2);
let formattedComments = '';
if (last2.length > 0) {
  formattedComments = last2.map(c => `User @${c.user?.login || 'unknown'}: ${c.body || ''}`).join('\n\n');
}

return [{
  json: {
    ...payload,
    last2Comments: formattedComments
  }
}];

const output = $input.first().json.stdout || '';
const needsInput = output.includes('NEEDS_INPUT:');
let question = '';
if (needsInput) {
  const match = output.match(/NEEDS_INPUT:\s*(.+)/);
  question = match ? match[1].trim() : 'Agent needs additional information.';
}
return [{ json: { ...$input.first().json, needsInput, agentQuestion: question } }];

